#!/usr/bin/env node
/**
 * generate_guide.js — PDD User Interview Guide .docx generator
 *
 * Styled after the Infinum/ETR document template:
 *   - "∞ INFINUM" top-right header on every page
 *   - Client name + date top-left on page 1
 *   - Large bold document title
 *   - Red (#E8392A) horizontal rule under title
 *   - Section headings bold, larger, dark
 *   - Sub-section headings (###) in grey italic
 *   - Bold-able inline question text (**text**)
 *   - Italic conditional notes (*text*)
 *   - Bullet and numbered lists with proper indentation
 *   - Lettered sub-items (a. b. c.) indented further
 */

const {
  Document, Packer, Paragraph, TextRun, Header, AlignmentType,
  LevelFormat, HeadingLevel, BorderStyle, TabStopType, TabStopPosition,
  PageNumber, NumberFormat, ShadingType, WidthType, Table, TableRow,
  TableCell, VerticalAlign, PageBreak, ImageRun
} = require('docx');
const fs = require('fs');
const path = require('path');

// ── Palette ─────────────────────────────────────────────────────────────
const INFINUM_RED  = "D8262D";
const DARK         = "1A1A1A";
const MID_GREY     = "777777";
const LIGHT_GREY   = "F2F2F2";
const SECTION_GREY = "555555";
const WHITE        = "FFFFFF";
const FONT         = "Helvetica Neue";

// ── Page geometry (DXA: 1440 = 1 inch) ─────────────────────────────────
const PAGE_W  = 12240;
const PAGE_H  = 15840;
const MARGIN  = 1080; // 0.75"
const MARGIN_TOP = 1440; // 1" top for header room

// Content width for tab calculations
const CONTENT_W = PAGE_W - MARGIN * 2; // 10080 DXA

// ── Helpers ──────────────────────────────────────────────────────────────

function run(text, opts = {}) {
  return new TextRun({
    text,
    font: FONT,
    size: opts.size || 22,           // 11pt default
    bold: opts.bold || false,
    italics: opts.italic || false,
    color: opts.color || DARK,
    ...opts.extra || {}
  });
}

function spacer(pts = 6) {
  return new Paragraph({
    children: [],
    spacing: { before: 0, after: 0, line: pts * 20 }
  });
}

// Parse inline **bold** and *italic* and *(italic notes)* into TextRun array
function parseInline(text, baseSize = 22, baseColor = DARK) {
  const runs = [];
  // Combined regex: **bold**, *italic*
  const regex = /\*\*(.+?)\*\*|\*(.+?)\*/g;
  let lastIndex = 0;
  let m;
  while ((m = regex.exec(text)) !== null) {
    // Plain text before match
    if (m.index > lastIndex) {
      runs.push(run(text.slice(lastIndex, m.index), { size: baseSize, color: baseColor }));
    }
    if (m[1] !== undefined) {
      // Bold markers are intentionally stripped — questions render in normal weight.
      runs.push(run(m[1], { size: baseSize, color: baseColor }));
    } else if (m[2] !== undefined) {
      // Italic
      runs.push(run(m[2], { size: baseSize, italic: true, color: MID_GREY }));
    }
    lastIndex = regex.lastIndex;
  }
  if (lastIndex < text.length) {
    runs.push(run(text.slice(lastIndex), { size: baseSize, color: baseColor }));
  }
  return runs.length ? runs : [run(text, { size: baseSize, color: baseColor })];
}

// ── Numbering config reference names ────────────────────────────────────
const NUM_BULLETS  = "bullets";
const NUM_NUMBERS  = "numbers";
const NUM_LETTERS  = "letters";
const NUM_SUBBULLETS = "subbullets";

function numberingConfig() {
  return [
    {
      reference: NUM_BULLETS,
      levels: [{
        level: 0, format: LevelFormat.BULLET, text: "•",
        alignment: AlignmentType.LEFT,
        style: { paragraph: { indent: { left: 540, hanging: 270 } },
                 run: { font: FONT, size: 22, color: DARK } }
      }]
    },
    {
      reference: NUM_NUMBERS,
      levels: [{
        level: 0, format: LevelFormat.DECIMAL, text: "%1.",
        alignment: AlignmentType.LEFT,
        style: { paragraph: { indent: { left: 540, hanging: 360 } },
                 run: { font: FONT, size: 22, color: DARK } }
      }]
    },
    {
      reference: NUM_LETTERS,
      levels: [{
        level: 0, format: LevelFormat.LOWER_LETTER, text: "%1.",
        alignment: AlignmentType.LEFT,
        style: { paragraph: { indent: { left: 900, hanging: 360 } },
                 run: { font: FONT, size: 22, color: DARK } }
      }]
    },
    {
      reference: NUM_SUBBULLETS,
      levels: [{
        level: 0, format: LevelFormat.BULLET, text: "–",
        alignment: AlignmentType.LEFT,
        style: { paragraph: { indent: { left: 900, hanging: 270 } },
                 run: { font: FONT, size: 22, color: MID_GREY } }
      }]
    },
  ];
}

// ── Paragraph builders ──────────────────────────────────────────────────

// Title (large, bold, dark)
function titlePara(text) {
  return new Paragraph({
    children: [run(text, { size: 52, bold: true, color: DARK })],
    spacing: { before: 200, after: 80 },
  });
}

// Red rule under title (simulated with paragraph bottom border)
function redRule() {
  return new Paragraph({
    children: [],
    spacing: { before: 0, after: 240 },
    border: {
      bottom: { style: BorderStyle.SINGLE, size: 12, color: INFINUM_RED, space: 0 }
    }
  });
}

// Client + date subtitle (small, grey)
function subtitlePara(text) {
  return new Paragraph({
    children: [run(text, { size: 20, color: MID_GREY })],
    spacing: { before: 0, after: 40 },
  });
}

// H2 section heading (bold, larger, dark — "What are we trying to learn?")
function h2Para(text) {
  return new Paragraph({
    children: [run(text, { size: 30, bold: true, color: DARK })],
    spacing: { before: 400, after: 160 },
  });
}

// H3 sub-section heading (medium, grey — "Warm-Up", "Background")
function h3Para(text) {
  return new Paragraph({
    children: [run(text, { size: 22, color: SECTION_GREY })],
    spacing: { before: 280, after: 80 },
    border: {
      bottom: { style: BorderStyle.SINGLE, size: 2, color: "DDDDDD", space: 4 }
    }
  });
}

// Body paragraph
function bodyPara(text) {
  return new Paragraph({
    children: parseInline(text),
    spacing: { before: 40, after: 80 },
  });
}

// Bullet item
function bulletPara(text, numRef = NUM_BULLETS) {
  return new Paragraph({
    numbering: { reference: numRef, level: 0 },
    children: parseInline(text),
    spacing: { before: 40, after: 40 },
  });
}

// Numbered item (1. 2. 3.)
function numberedPara(num, text, instance = 0) {
  // We manage the number text manually for bold support, but use DECIMAL format
  return new Paragraph({
    numbering: { reference: NUM_NUMBERS, level: 0, instance },
    children: parseInline(text),
    spacing: { before: 60, after: 60 },
  });
}

// Lettered sub-item (a. b. c.)
function letteredPara(text) {
  return new Paragraph({
    numbering: { reference: NUM_LETTERS, level: 0 },
    children: parseInline(text, 22, MID_GREY),
    spacing: { before: 30, after: 30 },
  });
}

// Sub-bullet (dash indent)
function subBulletPara(text) {
  return new Paragraph({
    numbering: { reference: NUM_SUBBULLETS, level: 0 },
    children: parseInline(text, 22, MID_GREY),
    spacing: { before: 30, after: 30 },
  });
}

// Horizontal rule (light grey)
function hrPara() {
  return new Paragraph({
    children: [],
    spacing: { before: 160, after: 160 },
    border: {
      bottom: { style: BorderStyle.SINGLE, size: 2, color: "DDDDDD", space: 0 }
    }
  });
}

// ── Header ──────────────────────────────────────────────────────────────
// Infinum logo, right-aligned, small — on every page.
// Locate the bundled brand asset (plugin-root/assets/logo-color.png). Accepts
// a --logo <path> override; falls back to the "∞ INFINUM" wordmark if no file.
// Infinum logo (logo-color.png) embedded as base64 so the header renders anywhere.
const LOGO_PNG_BASE64 = "";

function findLogo() {
  const candidates = [];
  const logoArg = process.argv.indexOf('--logo');
  if (logoArg !== -1 && process.argv[logoArg + 1]) candidates.push(process.argv[logoArg + 1]);
  candidates.push(
    path.join(__dirname, '..', 'assets', 'logo-color.png'),               // skill/assets/
    path.join(__dirname, '..', '..', '..', 'assets', 'logo-color.png')    // plugin-root/assets/
  );
  for (const c of candidates) {
    try { if (c && fs.existsSync(c)) return c; } catch (e) { /* ignore */ }
  }
  return null;
}

function makeHeader() {
  // Prefer a --logo override or an assets/logo-color.png if present; otherwise fall back to
  // the logo embedded in this script (so it always renders, even run from a temp dir).
  let data = null;
  const logoPath = findLogo();
  if (logoPath) { try { data = fs.readFileSync(logoPath); } catch (e) { /* ignore */ } }
  if (!data && LOGO_PNG_BASE64) { try { data = Buffer.from(LOGO_PNG_BASE64, "base64"); } catch (e) { /* ignore */ } }
  const headerChild = data
    ? new ImageRun({ type: "png", data, transformation: { width: 140, height: 20 } })  // ~6.98:1
    : run("∞  INFINUM", { size: 18, bold: true, color: INFINUM_RED });
  return new Header({
    children: [
      new Paragraph({
        children: [ headerChild ],
        alignment: AlignmentType.RIGHT,
        spacing: { before: 0, after: 0 },
        border: {
          bottom: { style: BorderStyle.SINGLE, size: 2, color: "DDDDDD", space: 6 }
        }
      })
    ]
  });
}

// ── Markdown parser → docx paragraphs ──────────────────────────────────
function parseMarkdown(md) {
  const lines = md.split('\n');
  const paragraphs = [];
  let i = 0;

  // Track numbering restarts by using a fresh reference key each numbered block
  let inNumberedBlock = false;
  let inLetterBlock = false;
  let numSection = 0;  // increments per H2 so question numbering restarts each section/interviewee

  while (i < lines.length) {
    const raw = lines[i];
    const s = raw.trim();

    // ── H1: # Title | Client | Date  (split on |)
    if (/^#\s/.test(s) && !/^##/.test(s)) {
      const content = s.replace(/^#\s+/, '');
      const parts = content.split('|').map(p => p.trim());
      if (parts[0]) paragraphs.push(titlePara(parts[0]));
      if (parts[1]) paragraphs.push(subtitlePara(parts.slice(1).join(' | ')));
      paragraphs.push(redRule());
      inNumberedBlock = false;
      i++; continue;
    }

    // ── H2: ## Section heading
    if (/^##\s/.test(s) && !/^###/.test(s)) {
      paragraphs.push(h2Para(s.replace(/^##\s+/, '')));
      inNumberedBlock = false;
      numSection++;   // restart question numbering for each new section / interviewee
      i++; continue;
    }

    // ── H3: ### Sub-section heading
    if (/^###\s/.test(s)) {
      paragraphs.push(h3Para(s.replace(/^###\s+/, '')));
      inNumberedBlock = false;
      i++; continue;
    }

    // ── HR
    if (/^---+$/.test(s)) {
      paragraphs.push(hrPara());
      inNumberedBlock = false;
      i++; continue;
    }

    // ── Lettered sub-item: a. b. c.
    if (/^[a-z]\.\s/.test(s)) {
      const text = s.replace(/^[a-z]\.\s+/, '');
      paragraphs.push(letteredPara(text));
      i++; continue;
    }

    // ── Numbered list item: 1. 2. etc.
    const numMatch = s.match(/^(\d+)\.\s+(.*)/);
    if (numMatch) {
      paragraphs.push(numberedPara(parseInt(numMatch[1]), numMatch[2], numSection));
      i++; continue;
    }

    // ── Bullet item: - or *
    if (/^[-*•]\s/.test(s)) {
      const text = s.replace(/^[-*•]\s+/, '');
      // Sub-bullets (deeper indent lines starting with spaces + dash)
      if (raw.match(/^\s{2,}[-*•]\s/)) {
        paragraphs.push(subBulletPara(text));
      } else {
        paragraphs.push(bulletPara(text));
      }
      i++; continue;
    }

    // ── Empty line
    if (!s) {
      paragraphs.push(spacer(8));
      i++; continue;
    }

    // ── Default: body paragraph
    paragraphs.push(bodyPara(s));
    i++;
  }

  return paragraphs;
}

// ── Main ─────────────────────────────────────────────────────────────────
const args = process.argv.slice(2);
const contentArg = args.indexOf('--content');
const outputArg  = args.indexOf('--output');

if (contentArg === -1 || outputArg === -1) {
  console.error('Usage: node generate_guide.js --content <file.md> --output <file.docx>');
  process.exit(1);
}

const contentPath = args[contentArg + 1];
const outputPath  = args[outputArg + 1];

if (!fs.existsSync(contentPath)) {
  console.error(`Content file not found: ${contentPath}`);
  process.exit(1);
}

const md = fs.readFileSync(contentPath, 'utf8');
const children = parseMarkdown(md);

const doc = new Document({
  numbering: { config: numberingConfig() },
  styles: {
    default: {
      document: { run: { font: FONT, size: 22, color: DARK } }
    },
    paragraphStyles: [
      {
        id: "Normal", name: "Normal", quickFormat: true,
        run: { font: FONT, size: 22, color: DARK },
        paragraph: { spacing: { line: 276, lineRule: "auto" } }
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: PAGE_W, height: PAGE_H },
        margin: { top: MARGIN_TOP, bottom: MARGIN, left: MARGIN, right: MARGIN }
      }
    },
    headers: { default: makeHeader() },
    children
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, buffer);
  console.log(`Saved: ${outputPath}`);
}).catch(err => {
  console.error('Error generating document:', err);
  process.exit(1);
});
